    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    mid = n // 2
    if n % 2 == 0:
        return (nums_sorted[mid - 1] + nums_sorted[mid]) / 2
    else:
        return float(nums_sorted[mid])

def c_to_f(c: float) -> float:
    f = c * 9/5 + 32
    return round(f, 1)

def dedupe(xs: list) -> list:
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result
